function glitch(el,text){let busy=false;const burst=()=>{if(busy)return;busy=true;el.classList.add("on");let n=0;const id=setInterval(()=>{n++;const s=[...text].map(c=>c===" "||c==="|"||Math.random()>.22?c:GL[Math.random()*GL.length|0]).join("");el.textContent=s;el.dataset.t=s;if(n>6){clearInterval(id);el.textContent=text;el.dataset.t=text;el.classList.remove("on");busy=false}},55)};
 el.textContent=text;el.dataset.t=text;el.addEventListener("mouseenter",burst);if(reduced)return;let t;const loop=()=>{t=setTimeout(()=>{burst();loop()},1800+Math.random()*2800)};const f=setTimeout(burst,900);loop();onClean(()=>{clearTimeout(t);clearTimeout(f)})}
