function marquees(root){const vel=()=>window.__vel||0;$$(".track",root).forEach(tr=>{const dir=+tr.dataset.dir,sp=+tr.dataset.sp;let w=0,x=0,last=performance.now(),raf,vis=true;const meas=()=>{w=tr.scrollWidth/6;if(dir<0&&x===0)x=w};meas();const ro=new ResizeObserver(meas);ro.observe(tr);const io=new IntersectionObserver(([e])=>vis=e.isIntersecting);io.observe(tr);
 const loop=n=>{raf=requestAnimationFrame(loop);const dt=Math.min(.05,(n-last)/1e3);last=n;if(!vis||reduced||!w)return;x+=dir*(sp+Math.min(Math.abs(vel())*38,900))*dt;if(x>=w)x-=w;if(x<0)x+=w;tr.style.transform=`translate3d(${-x}px,0,0)`};raf=requestAnimationFrame(loop);onClean(()=>{cancelAnimationFrame(raf);ro.disconnect();io.disconnect()})})}
const track=(items,dir,sp)=>{const set=items.map(t=>`<span>${t}<i>•</i></span>`).join("");return `<div class="track" data-dir="${dir}" data-sp="${sp}" aria-hidden="true">${`<div>${set}</div>`.repeat(6)}</div>`};
