 const V="attribute vec2 p;varying vec2 v;void main(){v=p*.5+.5;gl_Position=vec4(p,0.,1.);}";
 const F="precision highp float;uniform sampler2D t;uniform vec2 m;uniform float e;uniform float time;uniform vec2 res;varying vec2 v;void main(){vec2 uv=v;float asp=res.x/res.y;vec2 d=(uv-m)*vec2(asp,1.);float r=length(d);float infl=exp(-r*r*12.)*e;vec2 dir=d/(r+.0001);float wave=sin(r*34.-time*6.)*.5+.5;vec2 off=dir*infl*(.02+.022*wave);off+=vec2(sin(uv.y*16.+time*1.4),cos(uv.x*11.+time*1.1))*.0022;vec4 cr=texture2D(t,uv-off*1.25),cg=texture2D(t,uv-off),cb=texture2D(t,uv-off*.75);float a=max(cr.a,max(cg.a,cb.a));vec3 col=vec3(cr.r,cg.g,cb.b);vec3 yel=vec3(1.,.839,.039)*a;col=mix(col,yel,clamp(infl*1.6,0.,.7));gl_FragColor=vec4(col,a);}";
 const sh=(t,s)=>{const o=gl.createShader(t);gl.shaderSource(o,s);gl.compileShader(o);if(!gl.getShaderParameter(o,gl.COMPILE_STATUS))throw 0;return o};let pr;try{pr=gl.createProgram();gl.attachShader(pr,sh(gl.VERTEX_SHADER,V));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,F));gl.linkProgram(pr);if(!gl.getProgramParameter(pr,gl.LINK_STATUS))throw 0}catch(e){return}
 gl.useProgram(pr);gl.bindBuffer(gl.ARRAY_BUFFER,gl.createBuffer());gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);const loc=gl.getAttribLocation(pr,"p");gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
 const U=n=>gl.getUniformLocation(pr,n),uM=U("m"),uE=U("e"),uT=U("time"),uR=U("res"),tex=gl.createTexture();gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL,true);gl.enable(gl.BLEND);gl.blendFunc(gl.ONE,gl.ONE_MINUS_SRC_ALPHA);
 const off=document.createElement("canvas");let alive=true,vis=true,raf,mx=.5,my=.5,tx=.5,ty=.5,en=0,lastMove=0;const dpr=Math.min(devicePixelRatio||1,2),fam=getComputedStyle(h1).fontFamily;
 const build=async()=>{try{await document.fonts.load(`700 120px ${fam}`);await document.fonts.ready}catch(e){}const W=box.clientWidth;if(!W)return;const pc=off.getContext("2d");pc.font=`700 100px ${fam}`;try{pc.letterSpacing="-0.04em"}catch(e){}const w100=pc.measureText("EMMANUEL").width||1,fs=Math.min(100*W/w100,420),lh=fs*.84,H=Math.ceil(fs*.74+lh+fs*.06);
  h1.style.fontSize=fs+"px";h1.style.lineHeight=lh+"px";box.style.height=H+"px";off.width=Math.round(W*dpr);off.height=Math.round(H*dpr);cv.width=off.width;cv.height=off.height;const c=off.getContext("2d");c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,W,H);c.font=`700 ${fs}px ${fam}`;try{c.letterSpacing="-0.04em"}catch(e){}c.textBaseline="alphabetic";
  c.fillStyle="#fff";c.fillText("EMMANUEL",0,fs*.74);c.lineWidth=Math.max(2,fs*.012);c.strokeStyle="#fff";c.lineJoin="round";c.strokeText("AJAVON",0,fs*.74+lh);
  gl.bindTexture(gl.TEXTURE_2D,tex);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,off);[[gl.TEXTURE_MIN_FILTER,gl.LINEAR],[gl.TEXTURE_MAG_FILTER,gl.LINEAR],[gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE],[gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE]].forEach(a=>gl.texParameteri(gl.TEXTURE_2D,a[0],a[1]));gl.viewport(0,0,cv.width,cv.height);gl.uniform2f(uR,cv.width,cv.height);box.classList.add("ready")};
 const mv=e=>{const r=cv.getBoundingClientRect(),nx=(e.clientX-r.left)/r.width,ny=1-(e.clientY-r.top)/r.height,d=Math.hypot(nx-tx,ny-ty);tx=nx;ty=ny;if(nx>-.15&&nx<1.15&&ny>-.35&&ny<1.35){en=Math.min(1,en+d*5+.04);lastMove=performance.now()}};addEventListener("pointermove",mv,{passive:true});
 const coarse=matchMedia("(pointer:coarse)").matches,t0=performance.now();const frame=now=>{if(!alive)return;raf=requestAnimationFrame(frame);if(!vis)return;const t=(now-t0)/1e3;if(coarse||now-lastMove>4000){tx=.5+Math.cos(t*.7)*.38;ty=.5+Math.sin(t*1.1)*.3;en=Math.max(en,.42)}mx+=(tx-mx)*.1;my+=(ty-my)*.1;en*=.955;gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);gl.uniform2f(uM,mx,my);gl.uniform1f(uE,Math.min(1,en));gl.uniform1f(uT,t);gl.drawArrays(gl.TRIANGLE_STRIP,0,4)};
