/* ---------- Contact ---------- */
PAGES["/contact"]=()=>hero2("/ CONTACT",["Un stage,","un projet ?"],"Écris-moi : stage, site, application, IA ou collaboration. Je réponds dès que possible.")+`<section class="sec"><div class="wrap cgrid"><div id="cform"><form id="cf" novalidate><div style="position:absolute;left:-9999px" aria-hidden="true"><input id="hp" tabindex="-1" autocomplete="off"></div>
<div class="fg2"><label for="nm">Nom</label><input id="nm" class="field" autocomplete="name" placeholder="Ton nom"><p class="er" id="e-nm"></p></div>
<div class="fg2"><label for="em">E-mail</label><input id="em" type="email" class="field" autocomplete="email" placeholder="toi@exemple.com"><p class="er" id="e-em"></p></div>
<div class="fg2"><label for="tp">Sujet</label><select id="tp" class="field">${["Stage","Site web","Application web","IA","Design","Audit gratuit","Collaboration","Autre"].map(t=>`<option>${t}</option>`).join("")}</select></div>
<div class="fg2"><label for="ms">Message</label><textarea id="ms" rows="5" class="field" style="resize:none" placeholder="Parle-moi de ton projet, de ton stage, de ton idée…"></textarea><p class="er" id="e-ms"></p></div>
<div style="display:flex;gap:12px;flex-wrap:wrap"><button class="btn y" type="submit">Envoyer par e-mail</button><button class="btn o" type="button" id="cwa">Ou via WhatsApp</button></div><p class="muted" style="font-size:13px;margin-top:16px">Le bouton « e-mail » ouvre ton application de messagerie avec le message prêt à envoyer.</p></form></div>
<aside style="display:grid;gap:40px;align-content:start"><div><p class="mono" style="font-size:12px;color:rgba(255,255,255,.5)">E-mail</p><a href="mailto:${SITE.email}" class="d" style="display:inline-block;margin-top:8px;font-size:1.5rem;text-transform:none;letter-spacing:-.02em;text-decoration:underline;text-decoration-color:var(--y);text-underline-offset:8px;word-break:break-all">${SITE.email}</a></div><div><p class="mono" style="font-size:12px;color:rgba(255,255,255,.5)">Basé à</p><p class="d" style="font-size:1.5rem;text-transform:none;margin-top:8px">Dakar, Sénégal</p><p style="margin-top:8px;font-size:14px;color:rgba(255,255,255,.6);display:flex;gap:8px;align-items:center"><i class="dot"></i>Disponible pour stage &amp; projets</p></div><div style="border-top:1px solid rgba(255,255,255,.1)">${SITE.soc.map(s=>`<a class="lnk" href="${s[2]}" target="_blank" rel="noopener">${s[1]}<span>↗</span></a>`).join("")}</div></aside></div></section>`;
PAGES["/contact"].init=(r,q)=>{const f=id=>$("#"+id);if(q.get("sujet")==="audit"){f("tp").value="Audit gratuit";if(q.get("pseudo"))f("nm").value=q.get("pseudo");f("ms").value=`Bonjour Emmanuel, j'ai battu ton score dans HACK THE SYSTEM${q.get("score")?` (${q.get("score")} points)`:""}. Je voudrais mon audit gratuit pour le site suivant : `}
 const body=()=>`Nom : ${f("nm").value}\nE-mail : ${f("em").value}\nSujet : ${f("tp").value}\n\n${f("ms").value}`;
 $("#cwa").addEventListener("click",()=>open(`https://wa.me/${SITE.wa}?text=${encodeURIComponent(`Bonjour Emmanuel, je suis ${f("nm").value||"…"}. Sujet : ${f("tp").value}.\n\n${f("ms").value}`)}`,"_blank","noopener"));
 $("#cf").addEventListener("submit",e=>{e.preventDefault();if(f("hp").value)return;const er={nm:f("nm").value.trim().length<2?"Indique ton nom (2 caractères minimum).":"",em:/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(f("em").value.trim())?"":"Adresse e-mail invalide.",ms:f("ms").value.trim().length<10?"Ton message est trop court (10 caractères minimum).":""};Object.keys(er).forEach(k=>f("e-"+k).textContent=er[k]);if(Object.values(er).some(Boolean))return;
  try{const a=JSON.parse(localStorage.getItem("ea_msgs")||"[]");a.push({at:Date.now(),name:f("nm").value,email:f("em").value,topic:f("tp").value,message:f("ms").value});localStorage.setItem("ea_msgs",JSON.stringify(a))}catch(x){}
  const sub=`[Portfolio] ${f("tp").value} — ${f("nm").value}`,href=`mailto:${SITE.email}?subject=${encodeURIComponent(sub)}&body=${encodeURIComponent(body())}`;
  const who=esc(f("nm").value.split(" ")[0]);$("#cform").innerHTML=`<div style="border:1px solid var(--y);padding:clamp(28px,5vw,48px)" role="status"><p class="mono" style="font-size:12px;color:var(--y)">Message prêt</p><p class="d" style="font-size:clamp(2rem,5vw,3rem);margin-top:16px">Merci ${who}.</p><p class="muted" style="margin-top:16px;max-width:28rem">Ton application de messagerie va s'ouvrir avec le message pré-rempli : il te reste à cliquer sur « Envoyer ». Rien n'est parti tant que tu ne l'as pas fait.</p><div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:28px"><a class="btn y" href="${href}">Ouvrir mon e-mail</a><a class="btn o" target="_blank" rel="noopener" href="https://wa.me/${SITE.wa}?text=${encodeURIComponent(body())}">Envoyer sur WhatsApp</a></div></div>`;location.href=href})};

