if(matchMedia("(hover:hover) and (pointer:fine)").matches){const d=$("#cur");let x=0,y=0,tx=0,ty=0,big=false;addEventListener("pointermove",e=>{tx=e.clientX;ty=e.clientY;big=!!e.target.closest("a,button,input,textarea,select,label,.photo")},{passive:true});(function l(){x+=(tx-x)*.22;y+=(ty-y)*.22;d.style.transform=`translate3d(${x}px,${y}px,0) translate(-50%,-50%) scale(${big?3.2:1})`;requestAnimationFrame(l)})()}
